  "forge/src/gametest/java/net/morthen/template/gametest/GametestMod.java": {
   "text": "package net.morthen.template.gametest;\n\nimport net.minecraft.core.registries.Registries;\nimport net.minecraft.data.DataProvider;\nimport net.minecraft.gametest.framework.GameTestHelper;\nimport net.minecraftforge.data.event.GatherDataEvent;\nimport net.minecraftforge.fml.common.Mod;\nimport net.minecraftforge.fml.javafmlmod.FMLJavaModLoadingContext;\nimport net.minecraftforge.registries.DeferredRegister;\nimport net.morthen.example.gametest.GametestConstants;\nimport net.morthen.template.gametest.provider.GametestInstanceProvider;\n\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.function.Consumer;\n\n@Mod(GametestConstants.MOD_ID)\npublic class GametestMod {\n    public static final DeferredRegister<Consumer<GameTestHelper>> GAMETESTS = DeferredRegister.create(Registries.TEST_FUNCTION, GametestConstants.MOD_ID);\n    private static final List<String> testKeys = new ArrayList<>();\n\n    public GametestMod(FMLJavaModLoadingContext context) {\n        GametestConstants.LOGGER.info(\"Loading Gametest Mod\");\n        GametestConstants.initTests(GametestMod::registerTest);\n        GatherDataEvent.getBus(context.getModBusGroup()).addListener(GametestMod::gatherData);\n        GAMETESTS.register(context.getModBusGroup());\n    }\n\n    private static void registerTest(String name, Consumer<GameTestHelper> consumer) {\n        testKeys.add(name);\n        GAMETESTS.register(name, () -> consumer);\n    }\n\n    public static void gatherData(GatherDataEvent event) {\n        event.getGenerator().addProvider(true, (DataProvider.Factory<GametestInstanceProvider>) output -> new GametestInstanceProvider(output, testKeys));\n    }\n}\n"
  },
  "forge/src/gametest/java/net/morthen/template/gametest/provider/GametestInstanceProvider.java": {
   "text": "package net.morthen.template.gametest.provider;\n\nimport com.google.gson.JsonObject;\nimport net.minecraft.core.registries.Registries;\nimport net.minecraft.data.CachedOutput;\nimport net.minecraft.data.DataProvider;\nimport net.minecraft.data.PackOutput;\nimport net.minecraft.resources.Identifier;\nimport net.morthen.example.gametest.GametestConstants;\n\nimport java.util.Collection;\nimport java.util.concurrent.CompletableFuture;\n\npublic class GametestInstanceProvider implements DataProvider {\n    private final PackOutput.PathProvider pathProvider;\n    private final Collection<String> testKeys;\n\n    public GametestInstanceProvider(PackOutput output, Collection<String> testKeys) {\n        this.pathProvider = output.createRegistryElementsPathProvider(Registries.TEST_INSTANCE);\n        this.testKeys = testKeys;\n    }\n\n    @Override\n    public CompletableFuture<?> run(CachedOutput cache) {\n        return CompletableFuture.allOf(\n                this.testKeys.stream()\n                        .map(name -> {\n                            return DataProvider.saveStable(cache, buildTestInstance(name),\n                                    pathProvider.json(Identifier.fromNamespaceAndPath(GametestConstants.MOD_ID, name)));\n                        })\n                        .toArray(CompletableFuture[]::new)\n        );\n    }\n\n    private JsonObject buildTestInstance(String name) {\n        JsonObject json = new JsonObject();\n        json.addProperty(\"type\", \"minecraft:function\");\n        json.addProperty(\"environment\", \"minecraft:default\");\n        json.addProperty(\"function\", GametestConstants.MOD_ID + \":\" + name);\n        json.addProperty(\"structure\", \"minecraft:empty\");\n        json.addProperty(\"max_ticks\", 400);\n        json.addProperty(\"setup_ticks\", 50);\n        json.addProperty(\"required\", true);\n        return json;\n    }\n\n    @Override\n    public String getName() {\n        return \"Gametest Instance Provider\";\n    }\n}\n"
  },
